use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

#[gpui::test]
async fn test_spawn_order_and_drop_cancellation(cx: &gpui::TestAppContext) {
    // —— 实验一：两种 spawn 各启动一个打印任务 ——
    let foreground = cx.spawn(|_cx| async {
        println!("[1] 前台任务：运行在主线程");
    });

    let background = cx.background_spawn(async {
        println!("[2] 后台任务：运行在线程池");
    });

    // 先持有再一起释放，避免语句结束时临时 Task 被 drop 而取消
    std::mem::drop((foreground, background));
    cx.run_until_parked();
}
```

Hmm wait — dropping foreground/background tasks immediately cancels them! `std::mem::drop((foreground, background))` drops → cancels → nothing prints. That's wrong for experiment 1. To run them, either `.detach()` or keep them alive past run_until_parked:

```rust
let tasks = vec![
    cx.spawn(...),      // Task
    cx.background_spawn(...),
];
cx.run_until_parked();  // 两个任务都会执行（tasks 仍存活）
drop(tasks);            // 此时任务已完成，drop 无副作用
```

That's clean and teaches holding tasks in a field/vec. 

Experiment 2 (drop cancels):

```rust
#[gpui::test]
async fn test_drop_cancels(cx: &gpui::TestAppContext) {
    let finished = Arc::new(AtomicBool::new(false));
    let timer = cx.background_executor.timer(Duration::from_secs(60));

    let task = cx.background_spawn({
        let finished = finished.clone();
        async move {
            println!("[bg] 第一步：任务已启动");
            timer.await; // 停在假时钟的 60 秒处
            println!("[bg] 第二步：定时器到期");
            finished.store(true, Ordering::SeqCst);
        }
    });

    // 只推进一个任务轮次：第一步打印，任务挂在定时器上
    assert!(cx.background_executor.tick());

    drop(task); // 关键：drop 即取消
    cx.run_until_parked(); // 时钟再怎么推进，第二步也不会执行

    assert!(!finished.load(Ordering::SeqCst));
}
```

And a control experiment (对照): same task not dropped → finished == true after run_until_parked. Nice.

